import java.nio.file.*;import java.util.*;import java.util.jar.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
/** Compare old helper graph, normalizing only javac synthetic lambda numbering. */
public final class SummonGroupDelta {
 static final String H="local/lito381/server/NativeSummonOwnerLifecycle";
 static String name(String s){return s.startsWith("lambda$")?s.replaceFirst("\\$[0-9]+$",""):s;}
 static ClassNode read(JarFile j)throws Exception{var c=new ClassNode();new ClassReader(j.getInputStream(j.getJarEntry(H+".class")).readAllBytes()).accept(c,ClassReader.SKIP_DEBUG|ClassReader.SKIP_FRAMES);return c;}
 static byte[] body(MethodNode m){var clone=new MethodNode(Opcodes.ASM9,m.access,name(m.name),m.desc,m.signature,m.exceptions.toArray(String[]::new));m.accept(clone);clone.name=name(m.name);for(var i:clone.instructions)if(i instanceof InvokeDynamicInsnNode call)for(int n=0;n<call.bsmArgs.length;n++)if(call.bsmArgs[n] instanceof Handle handle&&handle.getOwner().equals(H)&&handle.getName().startsWith("lambda$"))call.bsmArgs[n]=new Handle(handle.getTag(),handle.getOwner(),name(handle.getName()),handle.getDesc(),handle.isInterface());var c=new ClassNode();c.version=Opcodes.V17;c.access=Opcodes.ACC_PUBLIC;c.name="SummonGroupComparison";c.superName="java/lang/Object";c.methods.add(clone);var w=new ClassWriter(0);c.accept(w);return w.toByteArray();}
 public static void main(String[]a)throws Exception{try(var old=new JarFile(a[0]);var next=new JarFile(a[1])){var x=read(old);var y=read(next);if(x.fields.size()!=y.fields.size())throw new AssertionError("field count");for(int i=0;i<x.fields.size();i++){var f=x.fields.get(i);var g=y.fields.get(i);if(!Objects.equals(f.name,g.name)||!Objects.equals(f.desc,g.desc)||!Objects.equals(f.value,g.value)||f.access!=g.access)throw new AssertionError("field delta");}int retained=0,changed=0;for(var m:x.methods){var matches=y.methods.stream().filter(n->name(n.name).equals(name(m.name))&&n.desc.equals(m.desc)).toList();if(matches.size()!=1)throw new AssertionError("old helper member missing/ambiguous "+m.name+m.desc);boolean same=Arrays.equals(body(m),body(matches.get(0)));if(m.name.equals("apply")||m.name.equals("release")){if(same)throw new AssertionError("missing entry change");changed++;}else{if(!same)throw new AssertionError("unrelated helper method "+m.name);retained++;}}if(changed!=2)throw new AssertionError("only two old helper entries change");for(var m:y.methods)if(x.methods.stream().noneMatch(n->name(n.name).equals(name(m.name))&&n.desc.equals(m.desc))&&!Set.of("statusAction","group","apply","release").contains(m.name)&&!m.name.startsWith("lambda$group$"))throw new AssertionError("unreviewed new helper method "+m.name);System.out.println("PASS only old apply/release entries change; retained helper methods="+retained+"; new group/overload methods only; all fields identical; lambda numbering normalized only");}}
}
